#include <coroutine>
struct Task{
 struct promise_type;
 using Handle=std::coroutine_handle<promise_type>;
 Handle h;
 explicit Task(Handle value):h(value){}
 Task(Task&& other):h(other.h){other.h=nullptr;}
 ~Task(){if(h)h.destroy();}
 struct promise_type{
  Task get_return_object(){return Task(Handle::from_promise(*this));}
  std::suspend_always initial_suspend()noexcept{return {};}
  std::suspend_always final_suspend()noexcept{return {};}
  void return_void()noexcept{}
  void unhandled_exception(){__builtin_trap();}
 };
};
Task run(int* out){*out=7;co_return;}

int main(){int n=0;{Task task=run(&n);task.h.resume();}return n!=7;}
